    "statement": "Para responder às questões de 02 a 05, leia o texto \n“Corredor ecológico: quando dois e dois são cinco”, do \nbiólogo brasileiro Fernando Reinach.\n\n1 Imagine que você é um sapo e vive em um pântano. Aí \nvem o homem e constrói uma rodovia, dividindo o local. Se \nvocê tentar passar da sua metade para a outra, o risco de \nser atropelado é alto. O resultado é que a estrada, apesar de \nquase não alterar a área total, criou dois pântanos isolados.\n\nHá muito tempo os ecólogos observaram que, quando o \ntamanho de um ecossistema é reduzido, ele se torna mais \nfrágil e corre um risco maior de se desestabilizar. Há muitas \nrazões teóricas para isso, como a diminuição da população \ncapaz de trocar genes entre si. É o caso do nosso sapo no \npântano, que agora só pode se casar com a metade das \nfêmeas a que tinha acesso antes da infeliz estrada.\n\nPara reduzir o impacto ambiental de projetos como \nesse, há muitos anos se exige a construção de um corredor \nentre as duas metades do ecossistema original. No caso,\n\nhaveria uma ponte para que a estrada passasse por cima e \nos animais por baixo.\n\nPor incrível que pareça, somente depois de um estudo \nexperimental controlado, feito nas reservas florestais da costa \nleste dos Estados Unidos, é que se pôde demonstrar o efeito \nbenéfico desses corredores ecológicos, comprovando como \neles são de fato capazes de aumentar a biodiversidade.\n\n5 Os pesquisadores abriram clareiras do tamanho de um \nquarteirão (de aproximadamente cem por cem metros) no \nmeio da floresta nativa. Algumas clareiras permaneceram \nisoladas, outras ficaram ligadas entre si por finos corredores desmatados. Os pesquisadores produziram uma grande \ncombinação de áreas desmatadas, todas do mesmo tamanho, mas algumas ligadas entre si.\n\nApós o desmatamento, que foi feito simultaneamente \nem todas as áreas, os pesquisadores mediram, ao longo dos \nanos, o retorno das espécies em cada clareira. [...] O que \nse observou é que ao longo desse período muitas espécies \nrecolonizaram as áreas desmatadas, mas nas áreas conectadas por corredores o número de espécies diferentes (a biodiversidade) era maior que nas áreas desconectadas. [...]\n\n(A longa marcha dos grilos canibais, 2010.)\n\nA divulgação científica tem a função de popularizar a ciência, democratizar o acesso ao conhecimento científico e \nestabelecer condições para a alfabetização científica. O texto \nde Fernando Reinach enquadra-se nessa categoria. Com a \nfinalidade de tornar seu texto mais leve e acessível, o autor \nrecorre, por vezes, a uma linguagem mais pessoal e informal, \nconforme se verifica em:",
