    "statement": "Na antiga União Soviética, o jornal do Partido Comunista, \no Pravda, cuja tradução quer dizer “verdade”, não titubeou: \ndefendeu o autoritarismo como a única história viável. Até \nmesmo países de reconhecida tradição liberal costumam \npatinar quando precisam lembrar de um passado que preferem esquecer. Esse é o caso do regime de Vichy na França \n(1940–1944), quando as elites locais colaboraram com o \nnazismo, ou mesmo da Espanha, que até hoje não consegue \nacertar suas contas com o período violento da Guerra Civil \n(1936–1939), que dividiu, e ainda divide, sua população. Mas \nsão os governos de raiz autoritária que costumam ser os mais \n“afiados” na hora de acionar esse tipo de expediente político. \nO nazismo de Adolf Hitler (1933–1945) inventou um passado \n“ariano” para os alemães: puro e não corrompido pelos \ndemais imigrantes e pessoas consideradas degeneradas.\n\n(Lilia Schwarcz. www.nexojornal.com.br, 08.04.2019. Adaptado.)\n\nA discussão contida no excerto evidencia que as narrativas \nhistóricas podem ser utilizadas para",
