    "statement": "A entrega do feudo ao vassalo era feita em uma cerimônia, dividida em três atos: homenagem, juramento de \nfidelidade e investidura. Na homenagem, o vassalo, colocando suas mãos entre as mãos de seu senhor, fazia uma \ndeclaração de vontade. Quanto ao juramento de fidelidade, \nera prestado pelo vassalo com a mão sobre o Evangelho. \nJá a investidura, aspecto material do contrato, consistia na \nconcessão do feudo através da entrega de um elemento que \no simbolizava, como um punhado de terra ou um ramo de \nárvore.\n\n(Maria de Nazareth Corrêa Accioli Lobato. “Relações feudo-vassálicas na \nInglaterra do século XII: uma perspectiva literária”. Brathair, 2014. Adaptado.)\n\nA cerimônia descrita no excerto, dividida em três atos, tinha \ncomo principal finalidade",
