    "statement": "Para responder às questões de 06 a 08, leia os capítulos \nCXXIII e CXXIV do romance Memórias Póstumas de Brás \nCubas, de Machado de Assis.\n\nO verdadeiro Cotrim\n\nNão obstante os meus quarenta e tantos anos, como \neu amasse a harmonia da família, entendi não tratar o casamento sem primeiro falar ao Cotrim. Ele ouviu-me e respondeu-me seriamente que não tinha opinião em negócio \nde parentes seus. [...]\n\nTalvez pareça excessivo o escrúpulo do Cotrim, a quem \nnão souber que ele possuía um caráter ferozmente honrado. \nEu mesmo fui injusto com ele durante os anos que se seguiram ao inventário de meu pai. Reconheço que era um modelo. [...] Não era perfeito, decerto; tinha, por exemplo, o sestro1 \nde mandar para os jornais a notícia de um ou outro benefício \nque praticava — sestro repreensível ou não louvável, concordo; mas ele desculpava-se dizendo que as boas ações \neram contagiosas, quando públicas; razão a que se não pode \nnegar algum peso. Creio mesmo (e nisto faço o seu maior \nelogio) que ele não praticava, de quando em quando, esses \nbenefícios senão com o fim de espertar a filantropia dos outros; e se tal era o intuito, força é confessar que a publicidade \ntornava-se uma condição sine qua non2. Em suma, poderia \ndever algumas atenções, mas não devia um real a ninguém.\n\nVá de intermédio\n\nQue há entre a vida e a morte? Uma curta ponte. Não \nobstante, se eu não compusesse este capítulo, padeceria o \nleitor um forte abalo, assaz danoso ao efeito do livro. Saltar \nde um retrato a um epitáfio, pode ser real e comum; o leitor, \nentretanto, não se refugia no livro, senão para escapar à vida. \nNão digo que este pensamento seja meu; digo que há nele \numa dose de verdade, e que, ao menos, a forma é pitoresca. \nE repito: não é meu.\n\n(Machado de Assis. Memórias póstumas de Brás Cubas, 2014.)\n\n1\u0007sestro: hábito.\n2\u0007sine qua non: indispensável, essencial.\n\nProcedimento característico da prosa madura de Machado \nde Assis, o narrador recorre à metalinguagem em:",
