    "statement": "Presume-se que tenham sido trazidos forçadamente para \no Brasil cerca de 40% dos africanos vitimados pela escravidão moderna. Foram eles e seus descendentes que constituí\nram a quase total força de trabalho existente durante os mais \nde trezentos anos em que vigorou a instituição escravocrata \nbrasileira. Assim, a escravidão acabou por penetrar todos os \naspectos da sociedade brasileira durante esse período. Tão \nintensa quanto a própria escravidão foram os tipos de resistência apresentados pelos sujeitos escravizados ao sistema \nque lhes fora imposto. A resistência revelou-se desde a recusa vã em deixar suas terras, famílias, culturas e histórias na \nÁfrica, passando pela rebelião durante a insalubre travessia \ndo Atlântico, até as formas mais radicais, como assassinato \nde seus escravizadores, nos locais de trabalho forçado.\n\n(Maria Jorge dos Santos Leite. “Tráfico atlântico, escravidão \ne resistência no Brasil”. Sankofa. Revista de História da África e\n\nde Estudos da Diáspora Africana, 2017. Adaptado.)\n\nSegundo o excerto, a experiência da diáspora africana no \nBrasil foi marcada pela",
