    "statement": "No período entre 1879 e 1912, as capitais do Norte, principalmente Manaus, Porto Velho e Belém, capitanearam uma \nguinada para se tornarem referências nacionais em termos \nde construção de esgotos, transporte, eletricidade, atividades culturais como cinema e teatro, levando à construção de \nteatros e casas de concerto monumentais, requintadas pela \ntradição europeia que a burguesia urbana visava imitar. Por \nisso, esse período ficou conhecido como a “Belle Époque da \nAmazônia”.\n\n(André Nogueira. https://aventurasnahistoria.com.br, 22.03.2019.)\n\nNo contexto descrito, a chamada “Belle Époque da Amazônia” foi caracterizada pela",
