    "difficulty": "Difícil",
    "statement": "Para responder às questões de 01 a 03, leia o início do texto \n“Teia de aranha não é cabelo nem macarrão”, do biólogo \nbrasileiro Fernando Reinach.\n\nVocê já deve ter visto uma aranha pendurada em um \núnico fio de sua teia. Deve ter observado como ela é capaz \nde aumentar rapidamente o comprimento do fio. Em poucos \nsegundos, uma aranha pode produzir mais de dez centímetros de fio. Imagine se nosso cabelo crescesse com essa \nvelocidade. Teríamos que nos barbear três vezes por dia.\n\nA diferença entre o processo de fabricação do fio de \ncabelo e do fio de seda das aranhas explica a diferença de \nvelocidade do crescimento. No caso do cabelo, as células \npresentes no bulbo capilar (o que chamamos de raiz) sintetizam as proteínas que constituem o fio e, à medida que \nessas proteínas ficam prontas, são adicionadas à ponta do \nfio localizada dentro do bulbo capilar, aumentando seu comprimento. O crescimento é lento e constante. No caso do fio \nde seda das aranhas, uma glândula produz as proteínas que \nvão constituir o fio, e essas proteínas são estocadas em um \npequeno saco. Quando a aranha quer sintetizar um pedaço \nde fio, as proteínas são ejetadas do saco através de tubos \nmuito finos, formando os fios.\n\nO mecanismo é semelhante a uma máquina de fazer \nmacarrão — que, ao fazer a massa passar por um orifício, \nforma os fios. O problema é que, no caso do macarrão, \npodemos esperar algumas horas para a massa secar e o \nmacarrão endurecer. No caso das aranhas, no momento em \nque o fio é ejetado, ele já tem que estar pronto para suportar \no peso do animal. Isso significa que o processo de solidificação precisa ser rápido. A novidade é que foi descoberto o \ntruque usado pelas aranhas para produzir rapidamente uma \ngrande quantidade de fio.\n\n(Folha de lótus, escorregador de mosquito, 2018.)\n\nO texto do biólogo Fernando Reinach é um artigo de divulgação científica. Uma característica textual que o afasta de um \nartigo científico acadêmico é o emprego de linguagem",
