    "detail": "Literatura — UEA 2026 Acompanhamento III",
    "difficulty": "Difícil",
    "statement": "Para responder às questões de 05 a 08, leia o conto “Uma \ngalinha” da escritora Clarice Lispector, que integra o livro \nLaços de família, cuja primeira edição data de 1960.\n\n1 Era uma galinha de domingo. Ainda viva porque não \npassava de nove horas da manhã.\n\nParecia calma. Desde sábado encolhera-se num canto \nda cozinha. Não olhava para ninguém, ninguém olhava para \nela. Mesmo quando a escolheram, apalpando sua intimidade \ncom indiferença, não souberam dizer se era gorda ou magra. \nNunca se adivinharia nela um anseio.\n\nFoi, pois, uma surpresa quando a viram abrir as asas de \ncurto voo, inchar o peito e, em dois ou três lances, alcançar a \nmurada do terraço. Um instante ainda vacilou — o tempo da \ncozinheira dar um grito — e em breve estava no terraço do vizinho, de onde, em outro voo desajeitado, alcançou um telhado. \n[...] A família foi chamada com urgência e consternada viu o \nalmoço junto de uma chaminé. O dono da casa, lembrando-se \nda dupla necessidade de fazer esporadicamente algum esporte e de almoçar, vestiu radiante um calção de banho e resolveu \nseguir o itinerário da galinha: em pulos cautelosos alcançou o \ntelhado onde esta, hesitante e trêmula, escolhia com urgência \noutro rumo. [...] Pouco afeita a uma luta mais selvagem pela \nvida, a galinha tinha que decidir por si mesma os caminhos a \ntomar, sem nenhum auxílio de sua raça. [...]\n\nSozinha no mundo, sem pai nem mãe, ela corria, arfava, \nmuda, concentrada. Às vezes, na fuga, pairava ofegante num \nbeiral de telhado e enquanto o rapaz galgava outros com dificuldade, tinha tempo de se refazer por um momento. E então \nparecia tão livre.\n\n5 Estúpida, tímida e livre. Não vitoriosa como seria um galo \nem fuga. Que é que havia nas suas vísceras que fazia dela \num ser? A galinha é um ser. É verdade que não se poderia \ncontar com ela para nada. Nem ela própria contava consigo, \ncomo o galo crê na sua crista. Sua única vantagem é que \nhavia tantas galinhas que morrendo uma surgiria no mesmo \ninstante outra tão igual como se fora a mesma.\n\nAfinal, numa das vezes em que parou para gozar sua \nfuga, o rapaz alcançou-a. Entre gritos e penas, ela foi presa. \nEm seguida carregada em triunfo por uma asa através das \ntelhas e pousada no chão da cozinha com certa violência. \nAinda tonta, sacudiu-se um pouco, em cacarejos roucos e \nindecisos.\n\nFoi então que aconteceu. De pura afobação a galinha \npôs um ovo. Surpreendida, exausta. Talvez fosse prematuro. Mas logo depois, nascida que fora para a maternidade, \nparecia uma velha mãe habituada. Sentou-se sobre o ovo e \nassim ficou, respirando, abotoando e desabotoando os olhos. \nSeu coração, tão pequeno num prato, solevava e abaixava \nas penas, enchendo de tepidez aquilo que nunca passaria de \num ovo. Só a menina estava perto e assistiu a tudo estarrecida. Mal porém conseguiu desvencilhar-se do acontecimento, \ndespregou-se do chão e saiu aos gritos:\n\n— Mamãe, mamãe, não mate mais a galinha, ela pôs um \novo! ela quer o nosso bem!\n\nTodos correram de novo à cozinha e rodearam mudos a \njovem parturiente. Esquentando seu filho, esta não era nem \nsuave nem arisca, nem alegre, nem triste, não era nada, era \numa galinha. O que não sugeria nenhum sentimento especial. O pai, a mãe e a filha olhavam já há algum tempo, sem \npropriamente um pensamento qualquer. Nunca ninguém acariciou uma cabeça de galinha. O pai afinal decidiu-se com \ncerta brusquidão:\n\n10 — Se você mandar matar esta galinha nunca mais comerei galinha na minha vida!\n\n— Eu também! jurou a menina com ardor.\nA mãe, cansada, deu de ombros.\nInconsciente da vida que lhe fora entregue, a galinha \npassou a morar com a família. [...] Uma vez ou outra, sempre \nmais raramente, lembrava de novo a galinha que se recortara \ncontra o ar à beira do telhado, prestes a anunciar. Nesses \nmomentos enchia os pulmões com o ar impuro da cozinha e, \nse fosse dado às fêmeas cantar, ela não cantaria, mas ficaria \nmuito mais contente. Embora nem nesses instantes a expressão de sua vazia cabeça se alterasse. Na fuga, no descanso, \nquando deu à luz ou bicando milho — era uma cabeça de galinha, a mesma que fora desenhada no começo dos séculos.\n\nAté que um dia mataram-na, comeram-na e passaram-se \nanos.\n\n(Laços de família, 2009.)\n\nNa construção do conto, Clarice Lispector mobiliza, sobretudo, o seguinte recurso expressivo:",
