    "statement": "Com o fim da Primeira Guerra Mundial, impôs-se à \nAlemanha uma paz punitiva, justificada pelo argumento \nde que o Estado era o único responsável pela guerra e \npor todas as suas consequências (a cláusula da “culpa de \nguerra”), para mantê-la permanentemente enfraquecida. \nIsso foi conseguido não tanto por perdas territoriais; essa \npaz punitiva foi, na realidade, assegurada privando-se a \nAlemanha de uma marinha e uma força aérea efetivas; \nlimitando-se seu exército a 100 mil homens; impondo-se \n“reparações” (pagamentos dos custos da guerra incorridos pelos vitoriosos) teoricamente infinitas; pela ocupação militar de parte da Alemanha Ocidental; e, não menos, \nprivando-se a Alemanha de todas as suas antigas colônias \nno ultramar. Com exceção das cláusulas territoriais, nada \nrestava do Tratado de Versalhes em meados da década \nde 1930.\n\n(Eric Hobsbawm. Era dos extremos: o breve século XX:\n\n1914-1991, 1995. Adaptado.)\n\nO cenário descrito no excerto contribuiu para",
