    "statement": "Segurança alimentar e segurança dos alimentos são dois \ntermos que, apesar de similares, têm significados diferentes. \nEnquanto o primeiro se refere à garantia de acesso regular e \nsuficiente aos alimentos, o segundo está relacionado à composição do alimento, garantindo isenção de contaminações \nquímicas, físicas ou biológicas. Embora o uso de agrotóxicos \ncontribua para reduzir perdas na produção agrícola, favorecendo a produção de alimentos em larga escala, seu uso \ninadequado pode deixar resíduos nos alimentos e causar \nimpactos ambientais.\n\nNesse contexto, o uso de agrotóxicos na agricultura traz um \ndilema ético em que o foco está",
